function disposeGroup(g){if(!g)return;g.traverse(o=>{if(o.geometry)o.geometry.dispose()})}
function rebuildCity(){if(cityGroup){scene.remove(cityGroup);disposeGroup(cityGroup)}cityGroup=new THREE.Group();for(let y=0;y<H;y++)for(let x=0;x<W;x++){let c=state.grid[y][x];if(c.terrain==='water')continue;let p=cellPos(x,y),poll=pollutionAt(x,y);if(poll>0.18)plane(cityGroup,p.x,p.y+.08,p.z,.82,.82,'#817b50',Math.min(.42,poll*.06));if(c.zone&&!c.building){let col=c.zone==='res'?'#83ba76':c.zone==='com'?'#e5b653':c.zone==='ind'?'#ac8e9e':c.zone==='fish'?'#8eb8ad':'#b5b880';plane(cityGroup,p.x,p.y+.09,p.z,.72,.72,col,.42)}if(c.building)buildStructure(cityGroup,x,y,c.building,c.level);if(selected&&selected.x===x&&selected.y===y){let m=new THREE.Mesh(new THREE.BoxGeometry(.98,.08,.98),new THREE.MeshBasicMaterial({color:'#fff2ae',wireframe:true}));m.position.set(p.x,p.y+.11,p.z);cityGroup.add(m)}}buildRoads(cityGroup);scene.add(cityGroup);updateTraffic()}
function resize(){if(!renderer||!camera)return;let r=sceneRoot.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}
function animate(t){requestAnimationFrame(animate);let dt=Math.min(.06,(t-lastFrame)/1000);lastFrame=t;if(speed>0){clockAccumulator+=dt*speed;while(clockAccumulator>=12){clockAccumulator-=12;advanceMonth()}}controls.update();moveVehicles(dt*speed);renderer.render(scene,camera)}
function cellUnderPointer(e){let r=renderer.domElement.getBoundingClientRect();mouse.x=((e.clientX-r.left)/r.width)*2-1;mouse.y=-((e.clientY-r.top)/r.height)*2+1;raycaster.setFromCamera(mouse,camera);let hit=raycaster.intersectObject(terrainMesh,false)[0];if(!hit)return null;let x=Math.floor(hit.point.x+W/2),y=Math.floor(hit.point.z+H/2);if(x<0||y<0||x>=W||y>=H)return null;return{x:x,y:y}}
function landCell(x,y){return x>=0&&y>=0&&x<W&&y<H&&state.grid[y][x].terrain!=='water'}
function roadNear(x,y){return[[x+1,y],[x-1,y],[x,y+1],[x,y-1]].some(p=>p[0]>=0&&p[1]>=0&&p[0]<W&&p[1]<H&&state.grid[p[1]][p[0]].road)}
function covered(x,y,type,r){for(let yy=Math.max(0,y-r);yy<=Math.min(H-1,y+r);yy++)for(let xx=Math.max(0,x-r);xx<=Math.min(W-1,x+r);xx++){let c=state.grid[yy][xx];if(c.building===type&&Math.abs(xx-x)+Math.abs(yy-y)<=r&&operating(c,xx,yy))return true}return false}
function utility(x,y,type,r){for(let yy=0;yy<H;yy++)for(let xx=0;xx<W;xx++)if(state.grid[yy][xx].building===type&&Math.abs(xx-x)+Math.abs(yy-y)<=r)return true;return false}
function counts(){let f={power:0,water:0,clinic:0,school:0,fire:0,police:0,park:0,beach:0,plaza:0,sports:0,library:0},zones={res:0,com:0,ind:0,fish:0,farm:0},filled={res:0,com:0,ind:0,fish:0,farm:0},roads=0;for(let c of state.grid.flat()){if(c.building&&f[c.building]!==undefined)f[c.building]++;if(c.zone){zones[c.zone]=(zones[c.zone]||0)+1;if(c.building)filled[c.zone]=(filled[c.zone]||0)+1}if(c.road)roads++}return{f,zones,filled,roads}}
function demand(){let c=counts();return{res:Math.max(8,Math.min(100,Math.round(68+state.population/20-c.zones.res*2.2-c.filled.res*1.4))),com:Math.max(6,Math.min(100,Math.round(56+state.population/36-c.zones.com*2-c.filled.com))),ind:Math.max(5,Math.min(100,Math.round(51+state.jobs/25-(c.zones.ind+c.zones.fish+c.zones.farm)*1.5-c.filled.ind-c.filled.fish-c.filled.farm)))}}
function operating(c,x,y){if(!c.building)return false;if(['power','water'].includes(c.building))return true;if(['park','beach','plaza','sports'].includes(c.building))return true;return utility(x,y,'power',8)&&utility(x,y,'water',8)}
function pollutionAt(x,y){let pollution=0;for(let yy=Math.max(0,y-5);yy<=Math.min(H-1,y+5);yy++)for(let xx=Math.max(0,x-5);xx<=Math.min(W-1,x+5);xx++){let c=state.grid[yy][xx],d=Math.abs(xx-x)+Math.abs(yy-y);if(d<=5&&c.building==='ind'&&operating(c,xx,yy))pollution=Math.max(pollution,Math.max(0,46-d*8))}return pollution}
function naturalAt(x,y){let n=0;for(let yy=Math.max(0,y-4);yy<=Math.min(H-1,y+4);yy++)for(let xx=Math.max(0,x-4);xx<=Math.min(W-1,x+4);xx++){let c=state.grid[yy][xx],d=Math.abs(xx-x)+Math.abs(yy-y);if(d>4)continue;if(c.terrain==='forest'||c.terrain==='shore')n+=d<=2?.7:.3;if(['park','beach','plaza','sports'].includes(c.building))n+=d<=2?1.5:.8}return Math.min(7,n)}
function nearbyCommerce(x,y){let n=0;for(let yy=Math.max(0,y-5);yy<=Math.min(H-1,y+5);yy++)for(let xx=Math.max(0,x-5);xx<=Math.min(W-1,x+5);xx++)if(state.grid[yy][xx].building==='com'&&operating(state.grid[yy][xx],xx,yy)&&Math.abs(xx-x)+Math.abs(yy-y)<=5)n++;return n}
function homeValue(x,y,c){let services=['clinic','police','fire','school'].reduce((s,t)=>s+(covered(x,y,t,7)?1:0),0),base=105+c.level*72+Math.min(130,nearbyCommerce(x,y)*34)+Math.round(naturalAt(x,y)*17)-Math.round(pollutionAt(x,y)*1.7)-(4-services)*24-(state.crime?36:0)-(state.epidemic?52:0);if(!operating(c,x,y))base-=105;return Math.max(20,base)}
function economy(){let c=counts(),homes=[],shops=[],factories=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){let tile=state.grid[y][x];if(!tile.building||!tile.zone)continue;if(tile.zone==='res')homes.push({tile,x,y});if(tile.zone==='com')shops.push({tile,x,y});if(['ind','fish','farm'].includes(tile.zone))factories.push({tile,x,y})}let activeHomes=homes.filter(h=>operating(h.tile,h.x,h.y)),activeShops=shops.filter(s=>operating(s.tile,s.x,s.y)),activeFactories=factories.filter(f=>operating(f.tile,f.x,f.y)),goodsMade=activeFactories.reduce((n,f)=>n+(f.tile.zone==='ind'?42:f.tile.zone==='fish'?34:30)*f.tile.level,0),goodsNeed=activeShops.length*30,goodsRatio=goodsNeed?Math.min(1,goodsMade/goodsNeed):1,avg=a=>a.length?a.reduce((n,v)=>n+v.tile.level,0)/a.length:0,resRank=avg(activeHomes),comRank=avg(activeShops)*goodsRatio,indRank=avg(activeFactories),tax=Math.floor(state.population*state.tax.res*.36*resRank+state.jobs*(state.tax.com*.12*comRank+state.tax.ind*.12*indRank)),upkeep=c.f.power*38+c.f.water*24+c.f.clinic*25+c.f.school*29+c.f.fire*24+c.f.police*24+c.f.park*9+c.f.beach*11+c.f.plaza*10+c.f.sports*16+c.f.library*17,homesPoll=activeHomes.length?activeHomes.reduce((n,h)=>n+pollutionAt(h.x,h.y),0)/activeHomes.length:0,env=Math.max(0,Math.min(100,Math.round(100-homesPoll*.75-factories.filter(f=>f.tile.zone==='ind').length*2+c.f.park*2))),traffic=c.roads<10?'혼잡':state.population/c.roads>14?'정체':'원활';return{c,tax,upkeep,env,traffic,d:demand(),homes,shops,factories,activeHomes,activeShops,activeFactories,goodsMade,goodsNeed,goodsRatio}}function toast(msg){let t=el('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function addLog(t){state.logs.unshift(t);state.logs=state.logs.slice(0,7)}
function incident(type,q){let incidents={crime:{icon:'🚨',title:'치안 공백 · 절도 신고',message:'순찰 인력이 부족해 절도 신고가 늘었습니다.',happy:-4,money:-140,field:'crime',duration:3},fire:{icon:'🔥',title:'소방 공백 · 작은 화재',message:'소방서가 부족해 화재 진압과 복구에 비용이 들었습니다.',happy:-7,money:-240,field:'fireRisk',duration:2},disease:{icon:'🦠',title:'보건 공백 · 계절성 감염',message:'보건 인력이 부족해 감염 환자가 늘었습니다.',happy:-6,money:-110,field:'epidemic',duration:4}},e=incidents[type];if(!e)return;state[e.field]=Math.max(state[e.field]||0,e.duration);state.happy=Math.max(12,state.happy+e.happy);state.money+=e.money;state.eventCount++;state.eventCooldown=3+Math.floor(Math.random()*2);let card=el('latestEvent');card.innerHTML='<span>'+e.icon+'</span><div><b>'+e.title+'</b><p>'+e.message+'</p></div>';el('eventCount').textContent='이벤트 '+state.eventCount;addLog(e.icon+' '+e.title+' · '+e.message);showEvent(e.icon+' '+e.title+' — '+e.message)}
