function roadEndpoint(x,y){for(let[xx,yy]of[[x+1,y],[x-1,y],[x,y+1],[x,y-1]])if(xx>=0&&yy>=0&&xx<W&&yy<H&&state.grid[yy][xx].road)return[xx,yy];return null}
function roadPath(from,to){let a=roadEndpoint(from.x,from.y),b=roadEndpoint(to.x,to.y);if(!a||!b)return[];let start=a[1]*W+a[0],goal=b[1]*W+b[0],queue=[start],prev=new Map([[start,-1]]);for(let i=0;i<queue.length;i++){let id=queue[i];if(id===goal)break;let x=id%W,y=Math.floor(id/W);for(let [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]){let ni=ny*W+nx;if(nx<0||ny<0||nx>=W||ny>=H||prev.has(ni)||!state.grid[ny][nx].road)continue;prev.set(ni,id);queue.push(ni)}}if(!prev.has(goal))return[];let path=[];for(let id=goal;id!==-1;id=prev.get(id)){path.push({x:id%W,y:Math.floor(id/W)})}path.reverse();return[{x:from.x,y:from.y},...path,{x:to.x,y:to.y}]}
